mapper.update:
UPDATE indicators_lib.lib_index_scheme


        SCHEME_DESCR = #{params.schemeDescr},


        SCHEME_SQL = #{params.schemeSql},


        SCHEME_COLUMS = #{params.schemeColums},


        SCHEME_CONDITON = #{params.schemeConditon},


        IS_PUBLIC_SCHEME = #{params.isPublicScheme},


        MODIFY_USERID = #{params.userId},


        MODIFY_DATE = #{params.date}


        IS_PUSH = #{params.IS_PUSH}


WHERE id = #{params.schemeId}

mapper.select:
select count(1) from indicators_lib.lib_index_scheme s
WHERE

    s.SCHEME_DESCR = #{params.schemeDescr} AND s.ID <> #{params.schemeId}


    s.SCHEME_DESCR = #{params.schemeDescr}

SELECT s.ID,s.SCHEME_DESCR,s.SCHEME_CONDITON, s.IS_PUBLIC_SCHEME,indicators_lib.f_get_IndexName(s.SCHEME_COLUMS) AS INDEX_NAME, CASE WHEN (SELECT COUNT(1) FROM indicators_lib.lib_public_scheme p WHERE p.ADD_USERID = '${params.userId}' AND p.SCHEME_ID = s.ID) > 0 THEN '1' ELSE '0' END AS STATE FROM indicators_lib.lib_index_scheme s WHERE S.IS_DELETE='1' AND IS_PUBLIC_SCHEME = '0'
AND s.SCHEME_DESCR LIKE '%${params.schemeDescr}%'
ORDER BY MODIFY_DATE DESC LIMIT ${params.pageSize} OFFSET ${params.page}
